export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity;
  const T = u / g, H = u * u / (2 * g), E = 2 * T;
  const t = sdk.clamp(time, 0, E);
  const yt = u * t - g * t * t / 2;
  const vt = u - g * t;
  const rel = t >= T;
  const tau = Math.max(0, t - T);
  const yd = rel ? yt : H;
  const vd = rel ? -g * tau : 0;
  const ad = rel ? -g : 0;
  const gy = 360, s = 140;
  const Y = (h) => gy - h * s;
  const ts = t < 0.03 ? 'At launch' : (Math.abs(t - T) < 0.005 ? 'At the top' : (t >= E - 0.005 ? 'At launch height' : (t < T ? 'Rising' : 'Falling')));
  const ds = !rel ? 'Held in place' : (t >= E - 0.005 ? 'At launch height' : (tau < 0.1 ? 'Just released' : 'Falling together'));
  const o = [];
  o.push(...sdk.panel({ id: 'lane.toss', x: 20, y: 40, w: 290, h: 360, title: 'Toss', state: ts }));
  o.push(...sdk.panel({ id: 'lane.drop', x: 330, y: 40, w: 290, h: 360, title: 'Drop', state: ds }));
  const bx1 = 150, bx2 = 460;
  o.push(...sdk.groundMark('mark.toss', bx1, gy + 13, 120, 'launch'));
  o.push(...sdk.groundMark('mark.drop', bx2, gy + 13, 120, 'launch'));
  o.push(...sdk.gate('gate.drop', bx2, Y(H) + 26, { open: rel, w: 40 }));
  if (rel) {
    o.push(sdk.circle('ghost.drop', bx2, Y(H), 26, { opacity: 0.3 }));
    o.push(sdk.circle('ghost.toss', bx1, Y(H), 26, { opacity: 0.3 }));
  }
  o.push(sdk.circle('ball.toss', bx1, Y(yt), 26));
  o.push(sdk.circle('ball.drop', bx2, Y(yd), 26));
  o.push(...sdk.vector('vec.v.toss', { x: bx1 - 26, y: Y(yt) }, { value: vt, direction: 'up' }, { scale: 14, label: 'v' }));
  o.push(...sdk.vector('vec.v.drop', { x: bx2 - 26, y: Y(yd) }, { value: vd, direction: 'up' }, { scale: 14, label: 'v' }));
  o.push(...sdk.vector('vec.a.toss', { x: bx1 + 26, y: Y(yt) }, { value: -g, direction: 'up' }, { scale: 7, label: 'a' }));
  o.push(...sdk.vector('vec.a.drop', { x: bx2 + 26, y: Y(yd) }, { value: ad, direction: 'up' }, { scale: 7, label: 'a' }));
  o.push(...sdk.callout(205, 120, ['v = ' + sdk.format(vt, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s²'], { id: 'callout.toss' }));
  o.push(...sdk.callout(515, 120, ['v = ' + sdk.format(vd, 2) + ' m/s', 'a = ' + sdk.format(ad, 1) + ' m/s²'], { id: 'callout.drop' }));
  const q = { launchSpeed: u, gravity: g, apexTime: T, apexHeight: H, tossedVelocity: vt, tossedAcceleration: -g, tossedHeight: yt, dropVelocity: vd, dropAcceleration: ad, dropHeight: yd };
  return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'tossedVelocity', value: vt }, { id: 'tossedAcceleration', value: -g }, { id: 'dropVelocity', value: vd }, { id: 'dropAcceleration', value: ad }] }, quantities: q };
}
